// ORACLE TREE: sglv23's BCSA local-branch PREFILL = flashinfer 0.6.15 BatchPrefillWithPagedKVCacheWrapper(NHD, fa2),
// planned by _BcsaFlashInfer._plan_extend: causal, window_left = W - 1, page 1, eager (no CUDA graph). Module variant
// use_swa=True (fi_batch_prefill_swa_config.inc, generated by flashinfer, copied unmodified). Same flags as the AOT
// module (-use_fast_math -O3 -DNDEBUG).
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <flashinfer/attention/mask.cuh>
#include <flashinfer/attention/scheduler.cuh>
#include <flashinfer/pos_enc.cuh>

#include "fi_batch_prefill_swa_config.inc"
#include <flashinfer/attention/variants.cuh>
#include <flashinfer/attention/prefill.cuh>

using namespace flashinfer;
using VariantSwa = DefaultAttention</*custom mask*/ false, /*sliding window*/ true, false, false>;

namespace {
void* g_fd[16] = {};
void* g_id[16] = {};
void* g_pind[16] = {};
int cur_dev() {
  int d = 0;
  cudaGetDevice(&d);
  return d & 15;
}
#define g_f g_fd[cur_dev()]
#define g_i g_id[cur_dev()]
#define g_pin g_pind[cur_dev()]
const size_t kF = 128ull << 20, kI = 8ull << 20;
}  // namespace

// q [T][24][256] (T = qo_indptr_host[bs]); k/v cache [pool][1][kvh][256]; kv_indptr/indices/last_page_len device int32
// with host copies of qo_indptr / kv_indptr. o [T][24][256] bf16, lse [T][24] fp32 (log2).
extern "C" int ak_oracle_bcsa_prefill(void* q, void* kc, void* vc, int* qo_indptr_dev, int* kv_indptr, int* kv_indices,
                                      int* last_page_len, const int* qo_indptr_host, const int* kv_indptr_host, int bs,
                                      int qo_heads, int kv_heads, int window_left, float sm_scale, void* o, float* lse,
                                      void* stream) {
  cudaStream_t s = static_cast<cudaStream_t>(stream);
  if (!g_f) {
    cudaMalloc(&g_f, kF);
    cudaMalloc(&g_i, kI);
    cudaMallocHost(&g_pin, kI);
  }
  const int total_rows = qo_indptr_host[bs];
  PrefillPlanInfo plan;
  cudaError_t e = PrefillPlan<int32_t>(g_f, kF, g_i, g_pin, kI, plan, const_cast<int*>(qo_indptr_host),
                                       const_cast<int*>(kv_indptr_host), total_rows, bs, qo_heads, kv_heads, 256, 256,
                                       1, /*cuda graph*/ false, 2, window_left, -1, false, 0, s);
  if (e != cudaSuccess) return (int)e;
  // PrefillPlan stages the plan through ONE pinned host buffer with an async H2D copy; the next call would
  // overwrite it before that copy runs. (flashinfer plans once per forward; this oracle plans per call.)
  cudaStreamSynchronize(s);
  PagedParams p;
  memset(&p, 0, sizeof(p));
  p.q = static_cast<DTypeQ*>(q);
  const int64_t strides[4] = {(int64_t)kv_heads * 256, (int64_t)kv_heads * 256, 256, 1};
  p.paged_kv = paged_kv_t<DTypeKV, IdType>(kv_heads, 1, 256, bs, QKVLayout::kNHD, static_cast<DTypeKV*>(kc),
                                           static_cast<DTypeKV*>(vc), strides, kv_indices, kv_indptr, last_page_len);
  p.q_indptr = qo_indptr_dev;
  p.o = static_cast<DTypeO*>(o);
  p.lse = lse;
  p.num_qo_heads = qo_heads;
  p.group_size = uint_fastdiv(qo_heads / kv_heads);
  p.q_stride_n = qo_heads * 256;
  p.q_stride_h = 256;
  p.window_left = window_left;
  p.logits_soft_cap = 0.0;
  p.sm_scale = sm_scale;
  p.rope_rcp_scale = 1.0;
  p.rope_rcp_theta = 1.0 / 1e4;
  DTypeO* tmp_v = nullptr;
  float* tmp_s = nullptr;
  char* ib = static_cast<char*>(g_i);
  char* fb = static_cast<char*>(g_f);
  p.request_indices = reinterpret_cast<IdType*>(ib + plan.request_indices_offset);
  p.qo_tile_indices = reinterpret_cast<IdType*>(ib + plan.qo_tile_indices_offset);
  p.kv_tile_indices = reinterpret_cast<IdType*>(ib + plan.kv_tile_indices_offset);
  p.o_indptr = reinterpret_cast<IdType*>(ib + plan.o_indptr_offset);
  p.kv_chunk_size_ptr = reinterpret_cast<IdType*>(ib + plan.kv_chunk_size_ptr_offset);
  if (plan.split_kv) {
    p.merge_indptr = reinterpret_cast<IdType*>(ib + plan.merge_indptr_offset);
    tmp_v = reinterpret_cast<DTypeO*>(fb + plan.v_offset);
    tmp_s = reinterpret_cast<float*>(fb + plan.s_offset);
  }
  p.padded_batch_size = plan.padded_batch_size;
  p.max_total_num_rows = plan.total_num_rows;
  p.partition_kv = plan.split_kv;
  switch (plan.cta_tile_q) {
    case 16:
      return (int)BatchPrefillWithPagedKVCacheDispatched<16, 256, 256, PosEncodingMode::kNone, false, MaskMode::kCausal,
                                                         VariantSwa, PagedParams>(p, tmp_v, tmp_s, false, s);
    case 64:
      return (int)BatchPrefillWithPagedKVCacheDispatched<64, 256, 256, PosEncodingMode::kNone, false, MaskMode::kCausal,
                                                         VariantSwa, PagedParams>(p, tmp_v, tmp_s, false, s);
    case 128:
      return (int)BatchPrefillWithPagedKVCacheDispatched<128, 256, 256, PosEncodingMode::kNone, false,
                                                         MaskMode::kCausal, VariantSwa, PagedParams>(p, tmp_v, tmp_s,
                                                                                                     false, s);
    default:
      return (int)cudaErrorInvalidValue;
  }
}
